"""Dispatch for block-scaled FP8 dense GEMM kernels."""

import ctypes
from functools import lru_cache
from typing import NamedTuple

import torch

from kestrel_kernels.arch import get_cuda_arch
from kestrel_kernels.cute_aot_runtime import AotFamily, get_raw_stream
from kestrel_kernels.fallback import is_cute_jit_enabled
from kestrel_kernels.fp8_block_gemm_cute.variants import (
    SM90_FP8_BLOCK_GEMM_FAMILY,
    make_sm90_fp8_block_gemm_variant,
)


def _jit_compile_fn_factory(variant):
    from scripts.precompile import cubin_bundles as _cubin_bundles

    return _cubin_bundles._compile_fp8_block_gemm_sm90_1d2d(variant)


_family = AotFamily(
    SM90_FP8_BLOCK_GEMM_FAMILY,
    jit_compile_fn=_jit_compile_fn_factory if is_cute_jit_enabled() else None,
)


class _Sm90Config(NamedTuple):
    block_m: int
    block_n: int
    block_k: int
    cluster_m: int
    cluster_n: int
    stages: int
    num_tma_threads: int
    num_math_threads: int
    smem_size: int
    swizzle_a_mode: int
    swizzle_b_mode: int
    swizzle_d_mode: int

    @property
    def cluster_size(self) -> int:
        return self.cluster_m * self.cluster_n

    @property
    def multicast_on_a(self) -> bool:
        return self.cluster_n > 1


def _check_2d(name: str, tensor: torch.Tensor) -> None:
    if tensor.ndim != 2:
        raise ValueError(f"{name} must be 2D, got {tensor.ndim}D")


def _check_stride_multiple(name: str, tensor: torch.Tensor, dim: int, multiple: int) -> None:
    if tensor.stride(dim) % multiple != 0:
        raise ValueError(
            f"{name} stride({dim}) must be divisible by {multiple}, "
            f"got stride={tensor.stride()}"
        )


def _align_up(value: int, alignment: int) -> int:
    return ((value + alignment - 1) // alignment) * alignment


def _ceil_div(value: int, divisor: int) -> int:
    return (value + divisor - 1) // divisor


def _gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a


def _is_power_of_two(value: int) -> bool:
    return value > 0 and (value & (value - 1)) == 0


def _get_swizzle_mode(block_size: int, elem_size: int) -> int:
    for mode in (128, 64, 32, 16):
        if (block_size * elem_size) % mode == 0:
            return mode
    raise AssertionError("unreachable")


class _Sm90StorageConfig(NamedTuple):
    load_block_m: int
    load_block_n: int
    store_block_m: int
    store_block_n: int
    swizzle_a_mode: int
    swizzle_b_mode: int
    swizzle_d_mode: int


class _Sm90PipelineConfig(NamedTuple):
    smem_size: int
    stages: int


class _Sm90Layout(NamedTuple):
    block_m: int
    block_n: int
    block_k: int
    cluster_m: int
    cluster_n: int

    @property
    def cluster_size(self) -> int:
        return self.cluster_m * self.cluster_n


def _sm90_storage_config(layout: _Sm90Layout) -> _Sm90StorageConfig:
    wgmma_m = 64
    load_block_m = layout.block_m
    load_block_n = layout.block_n
    store_block_m = layout.block_m
    store_block_n = layout.block_n
    return _Sm90StorageConfig(
        load_block_m,
        load_block_n,
        store_block_m,
        store_block_n,
        _get_swizzle_mode(layout.block_k, 1),
        _get_swizzle_mode(layout.block_k, 1),
        _get_swizzle_mode(store_block_n, 2),
    )


def _sm90_pipeline_config(
    layout: _Sm90Layout,
    storage: _Sm90StorageConfig,
    k: int,
) -> _Sm90PipelineConfig:
    smem_capacity = 232448
    max_stages = 16
    smem_d = _align_up(layout.block_m * layout.block_n * 2, 1024)
    smem_barriers = max_stages * 8 * 2
    smem_a_per_stage = storage.load_block_m * layout.block_k
    smem_b_per_stage = storage.load_block_n * layout.block_k
    smem_sfa_per_stage = _align_up(layout.block_m * 4, 128)
    sfb_rows = 1 if layout.block_k % layout.block_n == 0 else 2
    smem_extra_sfb = _align_up(_ceil_div(k, layout.block_k) * 4 * sfb_rows, 8)
    smem_extra = smem_d + smem_barriers + smem_extra_sfb
    smem_stage = smem_a_per_stage + smem_b_per_stage + smem_sfa_per_stage
    stages = min((smem_capacity - smem_extra) // smem_stage, max_stages)
    return _Sm90PipelineConfig(smem_extra + stages * smem_stage, stages)


def _sm90_layout_candidates(m: int, n: int, k: int, num_sms: int) -> list[_Sm90Layout]:
    del m
    block_m_candidates = (64, 128, 256)
    block_n_candidates = range(16, 193, 16)
    block_k = 128
    candidates: list[_Sm90Layout] = []
    for cluster_m in (1, 2):
        for cluster_n in (1, 2):
            if cluster_m * cluster_n > 2:
                continue
            if num_sms % (cluster_m * cluster_n) != 0:
                continue
            for block_m in block_m_candidates:
                for block_n in block_n_candidates:
                    if block_n > block_k:
                        gap = block_n - block_k
                        if block_n % gap != 0 and block_k % gap != 0:
                            continue
                    if block_m > 128 and block_n > 128:
                        continue
                    layout = _Sm90Layout(block_m, block_n, block_k, cluster_m, cluster_n)
                    storage = _sm90_storage_config(layout)
                    if storage.swizzle_a_mode % 64 != 0 or storage.swizzle_b_mode % 64 != 0:
                        continue
                    pipeline = _sm90_pipeline_config(layout, storage, k)
                    if pipeline.stages < 3 or (
                        block_m * block_n < 128 * 192 and pipeline.stages < 4
                    ):
                        continue
                    candidates.append(layout)
    return candidates


def _sm90_layout_score(m: int, n: int, k: int, num_sms: int, layout: _Sm90Layout) -> float:
    if m == 512 and n == 12288 and k == 2048:
        if layout == _Sm90Layout(128, 128, 128, 1, 1):
            # qwen36.gdn.in_proj_qkvz_fused.m512: BM128/BN128 ran 29.18 us
            # vs DeepGEMM 29.22 us. BN112/160 were 1.24-1.25x DeepGEMM,
            # BN176 failed correctness, and BN192 was 1.11x DeepGEMM.
            return -1.0
        if (
            layout.block_m == 128
            and layout.cluster_size == 1
            and 112 <= layout.block_n <= 192
        ):
            return float("inf")
    if (
        m >= 512
        and n >= 8192
        and k == 2048
        and layout.block_m == 256
    ):
        # Tried BM256/BN128 for Qwen/Moondream FC1/QKV M512-M1024:
        # SASS spills final accumulators (271 LDL / 274 STL) and runs
        # dense_mlp_fc1.m512 at 36.16 us vs 21.44 us with BM128/BN128.
        # Keep BM256 out of this regime until the BM256 CuTe lowering is
        # register-only like DeepGEMM.
        return float("inf")
    if (
        m == 512
        and n >= 8192
        and k == 2048
        and layout.cluster_size > 1
    ):
        # Tried clustered BM128/BN128 on dense_mlp_fc1/q_or_qkv M512:
        # normal dispatch picked it after excluding BM256, but it ran
        # 22.56-22.91 us vs 21.44 us for single-CTA BM128/BN128.
        return float("inf")
    if (
        layout.cluster_m > 1
        and layout.block_n >= 112
        and n <= 1280
        and k >= 4096
    ):
        # Tried this BM128/BN192 cluster-on-M regime on SigLIP FC2 crops6/7/11:
        # it was 1.36-1.43x DeepGEMM, while the selector's next-best
        # BM256/BN96 cluster-on-N candidate ran 0.97-0.98x DeepGEMM. Keep it
        # out of long-K, low-N FC2-like shapes until the cluster_m path is fixed.
        # Retried the same cluster-on-M family at BN112 on crops2 after
        # removing the single-CTA BN112 candidate: it ran 31.62 us vs 18.54 us
        # with BM128/BN128, so the lower BN112 boundary is also bad.
        return float("inf")
    if (
        layout.cluster_size == 1
        and layout.block_n == 112
        and n <= 1280
        and k >= 4096
    ):
        # Tried the single-CTA BN112 path on SigLIP FC2 crops1/2: crops1
        # was 20.86 us vs 15.04 us with BM64/BN128, and crops2 was 28.00 us
        # vs 18.54 us with BM128/BN128. Keep BN112 available for clustered
        # larger crops, but avoid this long-K low-N single-CTA regime.
        return float("inf")
    if (
        6144 <= m < 8000
        and n <= 1280
        and k >= 4096
    ):
        if layout == _Sm90Layout(128, 128, 128, 1, 1):
            # md.siglip.mlp_fc2 crops9/10: the score model picks BM256/BN128
            # cluster-on-N, but that CuTe DSL body spills 206 LDL / 198 STL
            # and runs ~1.45x DeepGEMM. BM128/BN128 single-CTA measured
            # 0.94x DeepGEMM on the same shapes, so prefer it until the
            # BM256 lowering is register-only like DeepGEMM.
            return -1.0
        if layout.block_m == 256 and layout.block_n == 128:
            return float("inf")
    if (
        m >= 8000
        and n <= 1280
        and k >= 4096
    ):
        if layout == _Sm90Layout(256, 96, 128, 1, 2):
            # md.siglip.mlp_fc2 large crops: the score model drifted to
            # BM256/BN112 at crops12 and BM256/BN128 at crops13. Measured on
            # H100, BN96 keeps crops11 neutral (68.80 us vs 68.77 us), improves
            # crops12 96.54 us -> 87.55 us, and fixes crops13 130.26 us ->
            # 88.74 us vs DeepGEMM 95.65 us.
            return -1.0
        if layout.block_m == 256 and layout.block_n >= 112 and layout.cluster_n == 2:
            return float("inf")
    num_blocks = _ceil_div(m, layout.block_m) * _ceil_div(n, layout.block_n)
    num_waves = _ceil_div(num_blocks, num_sms)
    wave_efficiency = num_blocks / (num_waves * num_sms)
    elem_size_ab = 1
    elem_size_d = 2
    l2_bytes_per_cycle = min(64.0 * num_sms, 8e6 / 1.3e3)
    l1_bytes_per_cycle = 128.0 * num_sms
    wgmma_m = 64
    num_bytes_l2 = (
        k
        * (layout.block_m / layout.cluster_n + layout.block_n / layout.cluster_m)
        * elem_size_ab
    )
    num_bytes_l1 = k * (layout.block_m + layout.block_n) * elem_size_ab
    num_bytes_l1_tc = (
        k * (max(wgmma_m, layout.block_m) + layout.block_n) * elem_size_ab
        + layout.block_m * layout.block_n * elem_size_d
    )
    num_bytes_l1_l2_d = layout.block_m * layout.block_n * elem_size_d
    num_l2_cycles = (num_bytes_l2 + num_bytes_l1_l2_d) * num_blocks / l2_bytes_per_cycle
    num_l1_cycles = (
        (num_bytes_l1 + num_bytes_l1_tc + num_bytes_l1_l2_d)
        * num_blocks
        / l1_bytes_per_cycle
    )
    if layout.cluster_size > 1 and num_waves <= 1:
        return float("inf")
    return max(num_l1_cycles, num_l2_cycles) / wave_efficiency


def _sm90_config_from_layout(layout: _Sm90Layout, k: int) -> _Sm90Config:
    storage = _sm90_storage_config(layout)
    pipeline = _sm90_pipeline_config(layout, storage, k)
    num_tma_threads = 128
    num_math_threads = 128 if layout.block_m <= 64 else 256
    return _Sm90Config(
        layout.block_m,
        layout.block_n,
        layout.block_k,
        layout.cluster_m,
        layout.cluster_n,
        pipeline.stages,
        num_tma_threads,
        num_math_threads,
        pipeline.smem_size,
        storage.swizzle_a_mode,
        storage.swizzle_b_mode,
        storage.swizzle_d_mode,
    )


def _select_sm90_config(m: int, n: int, k: int, num_sms: int) -> _Sm90Config:
    layout_candidates = _sm90_layout_candidates(m, n, k, num_sms)
    if not layout_candidates:
        raise ValueError(f"no SM90 FP8 block GEMM config for M={m}, N={n}, K={k}")
    layout = min(
        layout_candidates,
        key=lambda candidate: _sm90_layout_score(m, n, k, num_sms, candidate),
    )
    return _sm90_config_from_layout(layout, k)


def _sm90_num_1d_blocks_per_group(config: _Sm90Config, num_sms: int) -> int:
    best = 8
    best_usage = 1 << 60
    for candidate in (8, 16):
        if config.multicast_on_a:
            usage = candidate * config.block_n + _ceil_div(num_sms, candidate) * config.block_m
        else:
            usage = candidate * config.block_m + _ceil_div(num_sms, candidate) * config.block_n
        if usage < best_usage:
            best = candidate
            best_usage = usage
    return best


def _sm90_compile_m(m: int, n: int, k: int, num_sms: int, config: _Sm90Config) -> int:
    if config.cluster_size == 1 and not config.multicast_on_a:
        tiles_m = _ceil_div(m, config.block_m)
        tiles_n = _ceil_div(n, config.block_n)
        if (
            config.block_n == 16
            and config.block_k == 128
            and n <= 128
            and k >= 4096
            and tiles_m <= 4
        ):
            # DeepGEMM's low-M BN16 long-K path uses the generic dynamic-M
            # scheduler. Matching that source structure improves tau_wqwv
            # m64 10.832 -> 10.624 us and m256 11.104 -> 10.688 us on H100.
            # Keep the static path for larger M and short-K shared-down:
            # m512/m730 and shared_down.m64 regress with compile_m=0.
            return 0
        if tiles_m * tiles_n <= num_sms:
            if tiles_m == 1:
                return -3
            if _is_power_of_two(tiles_m):
                return -2
            if config.block_n == 16 and n <= 128:
                # DeepGEMM's dynamic-M scheduler is compact for low-M BN16,
                # but the non-power-of-two single-wave path pays extra
                # scheduler/control instructions in CuTe. Exact static M is
                # the better local tradeoff for m730 small-N cases on H100:
                # tau_wqwv exact 11.712 us vs generic 12.832 us, and
                # moe_router default 7.920 us -> exact 7.616 us.
                return m
            return -1
    return 0


def _sm90_runtime_m_tile_args(m: int, config: _Sm90Config) -> tuple[int, int, int]:
    tiles_m = _ceil_div(m, config.block_m)
    if _is_power_of_two(tiles_m):
        return tiles_m, tiles_m - 1, tiles_m.bit_length() - 1
    return tiles_m, 0, 0


@lru_cache(maxsize=None)
def _compile_sm90_1d2d(
    a_dtype: torch.dtype,
    b_dtype: torch.dtype,
    d_dtype: torch.dtype,
    m: int,
    n: int,
    k: int,
    num_sms: int,
    scale_a_mn_major: bool,
    block_m: int,
    block_n: int,
    block_k: int,
    cluster_m: int,
    cluster_n: int,
    stages: int,
    num_tma_threads: int,
    num_math_threads: int,
):
    from kestrel_kernels.fp8_block_gemm_cute.sm90_fp8_gemm_1d2d import (
        compile_sm90_fp8_gemm_1d2d,
    )
    from kestrel_kernels.fp8_block_gemm_cute.utils import torch2cute_dtype_map

    return compile_sm90_fp8_gemm_1d2d(
        torch2cute_dtype_map[a_dtype],
        torch2cute_dtype_map[b_dtype],
        torch2cute_dtype_map[d_dtype],
        static_m=m,
        static_n=n,
        static_k=k,
        num_sms=num_sms,
        scale_a_mn_major=scale_a_mn_major,
        block_m=block_m,
        block_n=block_n,
        block_k=block_k,
        cluster_m=cluster_m,
        cluster_n=cluster_n,
        stages=stages,
        num_tma_threads=num_tma_threads,
        num_math_threads=num_math_threads,
    )


@lru_cache(maxsize=None)
def _resolve_sm90_1d2d(
    a_dtype: torch.dtype,
    b_dtype: torch.dtype,
    d_dtype: torch.dtype,
    m: int,
    n: int,
    k: int,
    num_sms: int,
    scale_a_mn_major: bool,
):
    config = _select_sm90_config(m, n, k, num_sms)
    compile_m = _sm90_compile_m(m, n, k, num_sms, config)
    runtime_m_tiles, runtime_m_tile_mask, runtime_m_tile_shift = (
        _sm90_runtime_m_tile_args(m, config)
    )
    compiled = _compile_sm90_1d2d(
        a_dtype,
        b_dtype,
        d_dtype,
        compile_m,
        n,
        k,
        num_sms,
        scale_a_mn_major,
        config.block_m,
        config.block_n,
        config.block_k,
        config.cluster_m,
        config.cluster_n,
        config.stages,
        config.num_tma_threads,
        config.num_math_threads,
    )
    return (
        compiled,
        runtime_m_tiles,
        runtime_m_tile_mask,
        runtime_m_tile_shift,
        k // config.block_k,
    )


@lru_cache(maxsize=None)
def _resolve_sm90_1d2d_variant(
    m: int,
    n: int,
    k: int,
    num_sms: int,
    scale_a_mn_major: bool,
    use_pdl: bool,
):
    config = _select_sm90_config(m, n, k, num_sms)
    compile_m = _sm90_compile_m(m, n, k, num_sms, config)
    runtime_m_tiles, runtime_m_tile_mask, runtime_m_tile_shift = (
        _sm90_runtime_m_tile_args(m, config)
    )
    variant = make_sm90_fp8_block_gemm_variant(
        m=m,
        n=n,
        k=k,
        num_sms=num_sms,
        scale_a_mn_major=scale_a_mn_major,
        compile_m=compile_m,
        config=config,
        use_pdl=use_pdl,
    )
    return (
        variant,
        config,
        runtime_m_tiles,
        runtime_m_tile_mask,
        runtime_m_tile_shift,
        k // config.block_k,
    )


def _resolve_aot_bundle(variant):
    arch = get_cuda_arch()
    bundle = _family.resolve(variant, arch)
    if bundle is None:
        raise RuntimeError(
            f"No {SM90_FP8_BLOCK_GEMM_FAMILY} JIT/AOT variant for "
            f"{variant.variant_key} on arch={arch}. This standalone "
            "benchmark kernel is not shipped in AOT bundles; run from a "
            "source checkout with CuTe DSL/CUTLASS available."
        )
    return bundle


def fp8_block_gemm_nt(
    out: torch.Tensor,
    a: torch.Tensor,
    b: torch.Tensor,
    scale_a: torch.Tensor,
    scale_b: torch.Tensor,
    *,
    use_pdl: bool = False,
) -> None:
    """Compute ``out = dequant(a, scale_a) @ dequant(b, scale_b).T``.

    This is the narrow DeepGEMM-compatible SM90 1D2D contract: 2D K-major FP8
    A/B, FP32 block scales, BF16 output, no C/add/batch. ``scale_a`` may be
    row-major or MN-major/TMA-aligned; the MN-major layout is the fast path.
    """
    for name, tensor in (("out", out), ("a", a), ("b", b), ("scale_a", scale_a), ("scale_b", scale_b)):
        _check_2d(name, tensor)
    device = a.device
    for name, tensor in (("out", out), ("a", a), ("b", b), ("scale_a", scale_a), ("scale_b", scale_b)):
        if not tensor.is_cuda:
            raise ValueError(f"{name} must be a CUDA tensor")
        if tensor.device != device:
            raise ValueError(
                f"{name} device {tensor.device} must match a device {device}"
            )
    if torch.cuda.get_device_capability(a.device) != (9, 0):
        raise ValueError("fp8_block_gemm_nt currently supports exact SM90/H100 only")
    if a.dtype != torch.float8_e4m3fn:
        raise ValueError(f"a must be torch.float8_e4m3fn, got {a.dtype}")
    if b.dtype != a.dtype:
        raise ValueError(f"b dtype {b.dtype} must match a dtype {a.dtype}")
    if out.dtype != torch.bfloat16:
        raise ValueError(f"out must be bf16, got {out.dtype}")
    if scale_a.dtype != torch.float32 or scale_b.dtype != torch.float32:
        raise ValueError("scale_a and scale_b must be float32")

    m, k = a.shape
    n, bk = b.shape
    if bk != k:
        raise ValueError(f"b K={bk} must match a K={k}")
    if tuple(out.shape) != (m, n):
        raise ValueError(f"out shape {tuple(out.shape)} must be {(m, n)}")
    if k % 128 != 0:
        raise ValueError(f"K must be divisible by 128, got {k}")
    if n % 16 != 0:
        raise ValueError(f"N must be divisible by 16, got {n}")
    if a.stride(-1) != 1 or b.stride(-1) != 1 or out.stride(-1) != 1:
        raise ValueError("a, b, and out must be row-major/K-major contiguous in the last dim")
    _check_stride_multiple("a", a, 0, 16)
    _check_stride_multiple("b", b, 0, 16)
    _check_stride_multiple("out", out, 0, 8)
    expected_scale_a = (m, k // 128)
    expected_scale_b = ((n + 127) // 128, k // 128)
    if tuple(scale_a.shape) != expected_scale_a:
        raise ValueError(f"scale_a shape {tuple(scale_a.shape)} must be {expected_scale_a}")
    if tuple(scale_b.shape) != expected_scale_b:
        raise ValueError(f"scale_b shape {tuple(scale_b.shape)} must be {expected_scale_b}")
    scale_k_stride_multiple = _gcd(k // 128, 4)
    if scale_a.stride(-1) == 1:
        scale_a_mn_major = False
        _check_stride_multiple("scale_a", scale_a, 0, scale_k_stride_multiple)
    elif scale_a.stride(-2) == 1:
        scale_a_mn_major = True
        _check_stride_multiple("scale_a", scale_a, 1, 4)
    else:
        raise ValueError(
            "scale_a must be row-major with stride(-1)=1 or MN-major with stride(-2)=1, "
            f"got stride={scale_a.stride()}"
        )
    if scale_b.stride(-1) != 1:
        raise ValueError("scale_b must be row-major with K-scale contiguous")
    _check_stride_multiple("scale_b", scale_b, 0, scale_k_stride_multiple)
    if not scale_a_mn_major and k // 128 % 4 != 0:
        raise ValueError(
            "row-major scale_a requires K/128 divisible by 4; use MN-major scale_a "
            f"for K={k}"
        )
    if m == 0:
        return

    num_sms = torch.cuda.get_device_properties(a.device).multi_processor_count
    (
        variant,
        _config,
        runtime_m_tiles,
        runtime_m_tile_mask,
        runtime_m_tile_shift,
        runtime_k_blocks,
    ) = _resolve_sm90_1d2d_variant(m, n, k, num_sms, scale_a_mn_major, use_pdl)
    bundle = _resolve_aot_bundle(variant)
    tensors = [a, b, out, scale_a, scale_b]
    if len(bundle.memref_specs) != len(tensors):
        raise RuntimeError(
            f"fp8_block_gemm memref count mismatch for {variant.variant_key}: "
            f"ciface expects {len(bundle.memref_specs)}, got {len(tensors)}"
        )
    device_index = int(a.device.index or 0)
    bundle.aot._ensure_device(device_index)
    structs = [spec.build(t) for t, spec in zip(tensors, bundle.memref_specs)]
    scalars = [
        ctypes.c_int32(runtime_m_tiles),
        ctypes.c_int32(runtime_m_tile_mask),
        ctypes.c_int32(runtime_m_tile_shift),
        ctypes.c_int32(runtime_k_blocks),
    ]
    stream = ctypes.c_void_p(get_raw_stream(device_index))
    bundle.invoke(structs, scalars, stream)


def fp8_block_quant_gemm_nt(
    out: torch.Tensor,
    a: torch.Tensor,
    b: torch.Tensor,
    scale_a: torch.Tensor,
    scale_b: torch.Tensor,
    inp: torch.Tensor,
    *,
    use_pdl: bool = False,
) -> None:
    """Quantize BF16 activations into ``a`` and run block-scaled FP8 GEMM."""
    from kestrel_kernels.fp8_quant_cute import fp8_block_quant_cute
    from kestrel_kernels.fp8_quant_cute.dispatch import _use_persistent_block_quant

    if scale_a.stride(-1) == 1:
        scale_major = "k"
    elif scale_a.stride(-2) == 1:
        scale_major = "m"
    else:
        scale_major = ""
    effective_pdl = bool(
        use_pdl
        and inp.ndim == 2
        and _use_persistent_block_quant(int(inp.shape[1]), int(inp.shape[0]), scale_major)
    )
    fp8_block_quant_cute(a, scale_a, inp, use_pdl=effective_pdl)
    fp8_block_gemm_nt(out, a, b, scale_a, scale_b, use_pdl=effective_pdl)
